    public function run(): void
    {
        $subject = Subject::where('slug', 'cloud-computing')->firstOrFail();

        $quizzes = [
            [
                'title' => 'Cloud Advanced — Architecture distribuée et cohérence',
                'description' => 'Analysez les compromis de cohérence, de disponibilité, de partitionnement et de résilience dans des architectures distribuées.',
                'difficulty' => 'Advanced',
                'duration' => 30,
                'passing_score' => 70,
                'total_marks' => 10,
                'is_active' => true,
                'questions' => [
                    $this->q('Une plateforme de réservation accepte une commande dans une région, mais l’utilisateur peut ensuite la lire dans une autre région avant la réplication. Quelle conception réduit le risque de confirmer deux fois la même ressource ?', 'Attribuer une autorité d’écriture cohérente à chaque ressource et appliquer une stratégie de conflit explicite', ['Accepter les écritures indépendantes partout puis choisir arbitrairement la dernière valeur reçue', 'Augmenter le nombre de répliques sans modifier la gestion des conflits', 'Mettre en cache toutes les réponses sans durée d’expiration'], 'La réplication seule ne garantit pas l’unicité des écritures. Une autorité d’écriture, une contrainte d’unicité ou une résolution explicite des conflits est nécessaire selon le niveau de disponibilité recherché.'),
                    $this->q('Un service de catalogue doit rester consultable pendant une partition réseau entre deux régions. Les modifications peuvent apparaître avec quelques secondes de retard. Quel compromis est le plus cohérent ?', 'Privilégier une lecture disponible avec cohérence éventuelle, tout en définissant comment les conflits d’écriture sont résolus', ['Exiger une cohérence forte interrégionale sans accepter de latence ou d’indisponibilité supplémentaire', 'Désactiver toute réplication et lire exclusivement depuis une région indisponible', 'Considérer chaque réponse en cache comme la version faisant autorité'], 'Si l’application accepte un retard de propagation, la cohérence éventuelle peut maintenir les lectures disponibles. Les écritures concurrentes exigent toutefois une règle de résolution.'),
                    $this->q('Un service de paiement ne peut pas confirmer une transaction tant que le registre partagé n’a pas validé l’écriture. La latence est secondaire par rapport à l’exactitude. Quelle priorité d’architecture convient ?', 'Préserver la cohérence de l’écriture et rendre explicite le comportement lorsque le quorum ou le registre est indisponible', ['Répondre avec succès avant validation puis supposer que la réplication terminera toujours', 'Accepter plusieurs écritures concurrentes sans identifiant de transaction', 'Réduire le nombre de contrôles de cohérence pour minimiser la latence'], 'Pour une opération financière, confirmer avant la validation durable peut produire des états contradictoires. L’application doit définir sa réponse en cas d’indisponibilité du mécanisme de validation.'),
                    $this->q('Une API distribuée connaît des pointes qui provoquent des timeouts. Les clients réessaient immédiatement et la charge augmente encore. Quel changement traite le mieux la boucle d’amplification ?', 'Utiliser des délais avec backoff exponentiel et jitter, des limites de tentatives et une protection de capacité', ['Augmenter le nombre de tentatives sans délai afin que les requêtes réussissent plus vite', 'Remplacer toutes les erreurs par une réponse de succès', 'Désactiver les timeouts pour laisser les connexions ouvertes'], 'Des retries synchronisés peuvent amplifier une panne. Un backoff avec jitter, un budget de tentatives et une limitation de charge réduisent la pression sur le service dégradé.'),
                    $this->q('Un service de profil dépend d’un service de recommandation non critique. Une panne de recommandation rend actuellement les profils indisponibles. Quelle mesure améliore le découplage opérationnel ?', 'Définir un délai maximal, un circuit breaker et un résultat de repli qui permet de servir le profil sans recommandations', ['Augmenter le timeout jusqu’à ce que le service de recommandation réponde', 'Faire dépendre le stockage des profils du même service de recommandation', 'Réessayer indéfiniment chaque appel avant de répondre'], 'Une dépendance non essentielle ne devrait pas empêcher le parcours principal. Un circuit breaker limite les appels en échec, tandis qu’un fallback maintient une réponse dégradée acceptable.'),
                    $this->q('Deux régions traitent simultanément des événements de mise à jour de compte. L’ordre des événements est important pour un même compte. Quel mécanisme aide à préserver cet ordre sans sérialiser tout le système ?', 'Partitionner les événements par identifiant de compte et préserver l’ordre à l’intérieur de chaque partition', ['Traiter tous les événements dans une seule file globale à faible parallélisme', 'Répartir les événements au hasard entre consommateurs indépendants', 'Trier les événements selon l’heure d’arrivée dans chaque région après traitement'], 'Le partitionnement par clé permet de traiter en série les événements d’un même compte tout en conservant le parallélisme entre comptes distincts.'),
                    $this->q('Une application doit tolérer l’indisponibilité temporaire d’un service tiers, mais ne doit pas perdre les demandes entrantes. Quelle architecture est la plus adaptée ?', 'Persister les demandes dans une file durable, puis les traiter de manière asynchrone avec reprise et idempotence', ['Garder toutes les demandes en mémoire dans le processus web', 'Répondre en succès puis supprimer les demandes avant de les transmettre', 'Multiplier les appels synchrones au service tiers pendant sa panne'], 'Une file durable absorbe les pointes et permet de différer le traitement. L’idempotence évite les effets doubles lors des reprises.'),
                    $this->q('Un système multi-région doit éviter qu’une panne d’une région provoque une perte de données récemment confirmées. Quel paramètre doit être clarifié avant le choix de réplication ?', 'Le RPO acceptable et le niveau de confirmation durable requis avant de répondre au client', ['Le nombre de tableaux de bord utilisés par les équipes', 'Le format de nommage des sous-réseaux uniquement', 'La taille des images de conteneurs indépendamment du flux de données'], 'Le RPO décrit la perte de données tolérable. Le mode de réplication et le moment où une écriture est considérée durable doivent être choisis en fonction de cet objectif.'),
                    $this->q('Une équipe veut rendre une opération de création de commande idempotente malgré les retries d’API. Quelle approche est la plus robuste ?', 'Accepter une clé d’idempotence stable et enregistrer atomiquement son résultat avec la commande', ['Générer une nouvelle clé à chaque tentative du client', 'Dédupliquer les commandes en comparant seulement leurs montants', 'Répondre en succès sans enregistrer l’identifiant de la requête'], 'Une clé stable permet de reconnaître les répétitions d’une même intention. Son association atomique au résultat empêche les créations doubles après un timeout.'),
                    $this->q('Un service réparti sur plusieurs zones passe ses tests de charge, mais une panne de zone provoque une longue interruption pendant le basculement. Quelle vérification manque probablement ?', 'Des exercices de panne mesurant le comportement réel de détection, de bascule et de récupération', ['Une mesure supplémentaire de la capacité nominale dans la zone principale', 'Un test de couleur des alertes dans le tableau de bord', 'Une hausse de la durée de rétention des logs sans scénario de panne'], 'La redondance configurée ne prouve pas que la bascule fonctionne. Des essais contrôlés valident les mécanismes et révèlent les dépendances cachées.'),
                ],
            ],
            [
                'title' => 'Cloud Advanced — Identités, Zero Trust et protection des workloads',
                'description' => 'Évaluez les contrôles d’identité, les chemins d’accès et la réduction du rayon d’impact d’une compromission cloud.',
                'difficulty' => 'Advanced',
                'duration' => 30,
                'passing_score' => 70,
                'total_marks' => 10,
                'is_active' => true,
                'questions' => [
                    $this->q('Une fonction serverless ne lit que des objets d’un seul compartiment et écrit ses résultats dans un autre. Quelle attribution IAM est la plus appropriée ?', 'Un rôle d’exécution limité aux opérations et ressources précises, avec des identifiants temporaires', ['Une clé d’administrateur permanente partagée par toutes les fonctions', 'Un rôle qui autorise toutes les actions sur tous les compartiments du compte', 'Un compte humain doté de privilèges globaux et stocké dans les variables du code'], 'Le rôle de workload doit appliquer le moindre privilège et utiliser des identifiants temporaires. Les droits doivent être limités aux opérations nécessaires sur les ressources concernées.'),
                    $this->q('Une clé cloud apparait dans l’historique Git, puis est supprimée du dernier commit. Quelle réponse réduit réellement le risque ?', 'Révoquer immédiatement la clé, examiner son utilisation et retirer le secret de l’historique selon la procédure', ['Supprimer seulement la ligne du fichier courant et conserver la clé active', 'Rendre le dépôt privé sans modifier la clé exposée', 'Renommer la variable contenant la clé dans la branche principale'], 'Une clé déjà publiée peut avoir été copiée. Il faut la révoquer, vérifier les traces d’utilisation et traiter l’historique ainsi que les systèmes qui ont pu la récupérer.'),
                    $this->q('Un compte de service utilisé par un pipeline peut modifier les politiques IAM de production et déployer l’application. Quel contrôle réduit le mieux l’impact d’une compromission du pipeline ?', 'Séparer les identités et responsabilités, puis n’accorder à chaque étape que les permissions nécessaires', ['Stocker le mot de passe du compte dans un document partagé accessible à l’équipe', 'Ajouter une seconde clé permanente au même compte avec les mêmes droits', 'Désactiver les journaux IAM pour ne pas exposer les noms de ressources'], 'Le compromis d’un pipeline ne doit pas donner automatiquement le contrôle complet de l’environnement. Des identités séparées, des permissions minimales et des validations protègent les étapes sensibles.'),
                    $this->q('Une équipe exige MFA pour les administrateurs, mais utilise des rôles permanents très larges pour les opérations quotidiennes. Quelle amélioration Zero Trust complète le mieux MFA ?', 'Réduire les permissions permanentes et accorder des privilèges temporaires contrôlés selon le besoin', ['Remplacer MFA par des mots de passe plus longs', 'Autoriser tous les accès depuis le réseau interne sans vérification d’identité', 'Accorder les mêmes privilèges à tous les administrateurs afin de simplifier le support'], 'MFA protège l’authentification mais ne limite pas l’autorisation. Le moindre privilège et l’élévation temporaire réduisent l’impact d’un compte utilisé abusivement.'),
                    $this->q('Une règle réseau autorise tout trafic entre les sous-réseaux applicatifs et de données. Quelle démarche devrait précéder la réduction de cette règle ?', 'Cartographier les flux nécessaires puis définir des règles ciblées et vérifier les journaux après déploiement', ['Bloquer immédiatement tous les flux sans vérifier les dépendances', 'Remplacer la règle par une autorisation globale sur les ports usuels', 'Conserver la règle et demander aux équipes de surveiller les applications manuellement'], 'Le filtrage doit correspondre aux flux réellement nécessaires. La cartographie et le déploiement contrôlé réduisent les interruptions tout en diminuant la surface d’attaque.'),
                    $this->q('Une charge de travail Kubernetes doit lire un secret au démarrage. Quel choix évite le mieux d’incorporer le secret durablement à l’image ?', 'Récupérer le secret à l’exécution depuis un gestionnaire dédié au moyen d’une identité de workload limitée', ['Ajouter le secret dans une couche de l’image puis supprimer le fichier dans la couche suivante', 'Encoder le secret en Base64 dans le manifeste et le publier avec le code', 'Inscrire le secret dans les journaux de démarrage pour faciliter le diagnostic'], 'Les couches d’images et les manifests sont souvent conservés ou distribués. Le secret doit être injecté au moment de l’exécution, avec un accès contrôlé et une rotation possible.'),
                    $this->q('Une organisation chiffre les volumes mais plusieurs équipes partagent le même rôle de gestion des clés. Quel risque reste important ?', 'Une équipe ayant accès au rôle peut potentiellement déchiffrer des données au-delà de son besoin', ['Le chiffrement garantit la séparation des responsabilités même si le rôle est partagé', 'Les clés ne peuvent plus être auditées une fois utilisées', 'Les données chiffrées deviennent automatiquement publiques'], 'Le chiffrement protège les données stockées, mais la gouvernance des clés et des identités reste déterminante. Les droits de déchiffrement doivent être séparés et audités.'),
                    $this->q('Un nouveau service est accessible uniquement sur un réseau privé, mais chaque employé peut l’appeler avec un compte partagé. Pourquoi ce service n’est-il pas encore correctement protégé ?', 'La localisation privée du réseau ne remplace pas l’authentification individuelle, l’autorisation et la traçabilité', ['Tout service privé est sécurisé par définition, quel que soit le compte utilisé', 'Le seul risque restant est la capacité de stockage', 'Un compte partagé fournit une meilleure attribution des actions qu’une identité individuelle'], 'Zero Trust vérifie explicitement l’identité et les droits. Un réseau privé réduit certaines expositions, mais ne protège pas contre des identités abusées et nuit à l’attribution individuelle.'),
                    $this->q('Une entreprise doit détecter la création d’une nouvelle permission administrateur en dehors du processus approuvé. Quel signal opérationnel est le plus pertinent ?', 'Une alerte sur les changements IAM sensibles rapprochée de l’identité, de la ressource et du contexte de la requête', ['Une métrique de consommation CPU agrégée une fois par mois', 'Un rapport de disponibilité du stockage sans données d’identité', 'Une notification uniquement lorsqu’un utilisateur se connecte avec succès'], 'Les changements IAM peuvent ouvrir de nouveaux chemins d’accès. Les événements d’audit doivent être collectés et associés à une alerte sur les opérations à fort impact.'),
                    $this->q('Un administrateur doit effectuer une opération exceptionnelle sur une base de production. Quelle procédure concilie le mieux efficacité et contrôle ?', 'Élévation temporaire approuvée, limitée à la tâche, journalisée et automatiquement révoquée après l’intervention', ['Ajouter le compte à un groupe permanent d’administrateurs', 'Utiliser le compte de service d’une application pour éviter la revue', 'Demander à un collègue de transmettre ses identifiants personnels'], 'L’accès juste-à-temps réduit la durée d’exposition des privilèges. L’approbation, la limitation de portée et la journalisation rendent l’intervention contrôlable.'),
                ],
            ],
            [
                'title' => 'Cloud Advanced — Données, stockage et systèmes analytiques',
                'description' => 'Traitez les choix avancés de stockage, de cohérence, de protection et de gouvernance des données cloud.',
                'difficulty' => 'Advanced',
                'duration' => 30,
                'passing_score' => 70,
                'total_marks' => 10,
                'is_active' => true,
                'questions' => [
                    $this->q('Un pipeline analytique doit rejouer les transformations après une correction de code sans écraser les données d’origine. Quelle organisation de données soutient le mieux ce besoin ?', 'Conserver une zone source immuable et séparer les données préparées et les résultats dérivés', ['Écraser chaque fichier source avec la dernière transformation', 'Conserver uniquement les agrégats finaux sans référence à leur provenance', 'Déposer les fichiers bruts et calculés dans un répertoire non versionné commun'], 'La séparation entre données brutes et dérivées permet de rejouer le pipeline et d’expliquer l’origine des résultats sans altérer les sources.'),
                    $this->q('Un tableau de bord exige des lectures fortement cohérentes après mise à jour, mais son entrepôt analytique est alimenté de façon asynchrone. Quelle solution répond le mieux à l’exigence ?', 'Lire les vues transactionnelles autoritatives ou exposer explicitement le retard de fraîcheur avant de confirmer la mise à jour', ['Augmenter le nombre de partitions de l’entrepôt sans changer son mode d’alimentation', 'Présenter les données retardées comme immédiatement cohérentes', 'Désactiver la validation des transactions dans la base source'], 'Un pipeline asynchrone implique potentiellement un retard. Une exigence de lecture après écriture doit utiliser une source cohérente ou être traitée par une règle d’attente et de fraîcheur explicite.'),
                    $this->q('Un data lake reçoit des fichiers sans schéma documenté de plusieurs équipes. Les analystes ne savent pas lesquels sont fiables. Quel contrôle d’architecture apporte le plus de valeur ?', 'Mettre en place un catalogue avec propriétaire, schéma, classification, provenance et indicateurs de qualité', ['Augmenter la capacité du stockage sans modifier l’organisation des données', 'Renommer les fichiers selon leur date d’arrivée uniquement', 'Donner un accès complet à tous les analystes pour qu’ils identifient eux-mêmes les sources'], 'Un catalogue gouverné rend les données découvrables et interprétables. Le propriétaire, la provenance, le schéma et la qualité aident les utilisateurs à juger leur fiabilité.'),
                    $this->q('Une application écrit dans une base relationnelle managée avec réplication asynchrone vers une région secondaire. Après bascule, certaines transactions récentes manquent. Quelle propriété explique le mieux ce résultat ?', 'Le délai de réplication a laissé un écart entre la source et la réplique au moment de la panne', ['La réplication asynchrone garantit que toutes les écritures sont simultanément présentes', 'Une base relationnelle ne peut pas conserver de transactions', 'La bascule a transformé les données relationnelles en objets non persistants'], 'La réplication asynchrone peut perdre les écritures qui n’ont pas encore atteint la réplique. Le RPO et le mode de confirmation doivent être compatibles avec le besoin métier.'),
                    $this->q('Un bucket contient des sauvegardes et des fichiers de travail. Une règle de cycle de vie pourrait déplacer ou supprimer les sauvegardes avant la période de rétention requise. Quel contrôle est prioritaire ?', 'Tester les règles sur des préfixes représentatifs et protéger les objets soumis à une rétention obligatoire', ['Appliquer la règle directement à tout le bucket pour simplifier son administration', 'Désactiver les journaux afin d’éviter les alertes de cycle de vie', 'Compter sur la réplication pour conserver les objets supprimés sans vérification'], 'Les règles automatisées peuvent avoir des effets destructifs. Il faut tester leur portée et appliquer des contrôles de rétention aux données qui doivent être conservées.'),
                    $this->q('Des données personnelles sont copiées dans plusieurs régions pour accélérer l’analyse. L’organisation ne sait pas si la réplication respecte les restrictions applicables. Que faut-il établir avant d’étendre le pipeline ?', 'La classification, les lieux de traitement autorisés, les règles de réplication et les contrôles d’accès associés', ['Le débit maximal du réseau entre les régions uniquement', 'Un nom de bucket plus explicite sans examiner les copies existantes', 'La suppression de la documentation pour éviter toute ambiguïté'], 'La réplication modifie les lieux où les données sont stockées et traitées. La classification et les exigences de localisation doivent être reliées aux configurations et aux copies de sauvegarde.'),
                    $this->q('Un entrepôt de données interroge fréquemment les mêmes jeux de données, mais les coûts de lecture et de calcul augmentent fortement. Quelle analyse devrait être faite avant d’acheter davantage de capacité ?', 'Identifier les requêtes dominantes, leur fréquence, les données scannées et les possibilités de partitionnement ou de mise en cache', ['Augmenter la capacité sans mesurer les requêtes ni leur efficacité', 'Supprimer les journaux de requêtes afin de réduire les coûts de stockage', 'Déplacer toutes les tables vers la classe d’archivage'], 'Les coûts analytiques dépendent souvent des données lues, de la forme des requêtes et du calcul consommé. La mesure permet de cibler partitionnement, cache et optimisation.'),
                    $this->q('Une restauration récupère les fichiers mais pas les permissions, les métadonnées ni les dépendances nécessaires à leur exploitation. Quel défaut du plan est révélé ?', 'Le plan protège le contenu sans couvrir l’état complet requis pour restaurer le service utilisable', ['Le chiffrement au repos a supprimé les métadonnées', 'Les sauvegardes ne peuvent jamais contenir des données de configuration', 'Le RTO est nécessairement respecté dès que les fichiers existent'], 'Une reprise fonctionnelle peut nécessiter données, métadonnées, permissions, clés, configuration et dépendances. La restauration doit être testée de bout en bout.'),
                    $this->q('Un service de données doit conserver une trace vérifiable des transformations appliquées à chaque lot. Quel mécanisme facilite cette traçabilité ?', 'Enregistrer les identifiants de lots, versions de code et paramètres avec les résultats et journaux du pipeline', ['Écraser les fichiers sources après chaque traitement', 'Utiliser des noms de fichiers aléatoires sans registre', 'Conserver uniquement le dernier tableau de bord'], 'La traçabilité des entrées, transformations et versions permet d’expliquer ou de reproduire un résultat et de localiser une anomalie.'),
                    $this->q('Une table très consultée contient des données anciennes rarement utilisées et des données récentes soumises à des délais de réponse stricts. Quel principe peut optimiser stockage et service ?', 'Séparer ou hiérarchiser les données selon les profils d’accès et les exigences de latence, après validation des usages', ['Placer toutes les données en archivage froid afin de réduire la facture', 'Conserver toutes les données sur le stockage le plus coûteux sans mesurer les accès', 'Compresser les résultats uniquement après leur suppression'], 'Le tiering peut réduire les coûts si le placement respecte les besoins de latence, les fréquences d’accès et les règles de récupération.'),
                ],
            ],
            [
                'title' => 'Cloud Advanced — Kubernetes et sécurité des plateformes cloud-native',
                'description' => 'Diagnostiquez les risques de cluster, de chaîne d’approvisionnement, de réseau et d’isolation des workloads.',
                'difficulty' => 'Advanced',
                'duration' => 30,
                'passing_score' => 70,
                'total_marks' => 10,
                'is_active' => true,
                'questions' => [
                    $this->q('Un pod compromis peut lire les secrets de tous les namespaces parce que son service account possède un rôle cluster-admin. Quelle correction réduit le mieux son rayon d’impact ?', 'Créer un service account dédié avec un rôle limité aux seules ressources et opérations du workload', ['Ajouter une seconde copie des mêmes secrets dans chaque namespace', 'Exécuter tous les pods avec le même compte administrateur', 'Désactiver la journalisation RBAC pour réduire le bruit'], 'Un service account dédié et des permissions minimales empêchent un pod compromis d’obtenir un contrôle global inutile.'),
                    $this->q('Un cluster Kubernetes héberge des équipes ayant des niveaux de confiance différents. Les namespaces sont séparés, mais les pods peuvent toujours communiquer librement. Quel contrôle manque ?', 'Des politiques réseau appliquées et testées pour limiter les flux entre workloads', ['Une politique qui renomme automatiquement les namespaces', 'Un autoscaler avec une capacité maximale plus élevée', 'Un stockage partagé sans contrôle d’accès'], 'Les namespaces organisent les ressources mais ne constituent pas à eux seuls une frontière réseau. Des NetworkPolicies explicites limitent les communications autorisées.'),
                    $this->q('Une image est signée et provient d’un registre approuvé, mais une bibliothèque vulnérable y est détectée après publication. Quelle conclusion est correcte ?', 'La signature aide à vérifier provenance et intégrité, mais n’assure pas l’absence de vulnérabilités', ['La signature garantit que le code ne contient aucune vulnérabilité', 'Le registre approuvé rend inutile l’analyse des dépendances', 'Une image signée ne peut pas être modifiée par une mise à jour'], 'La signature permet de vérifier l’origine et l’intégrité de l’artefact. Le scan et la gestion des dépendances restent nécessaires pour détecter les vulnérabilités.'),
                    $this->q('Un nœud Kubernetes manque de mémoire et le kubelet termine des pods. Les limites mémoire semblent correctes individuellement, mais les demandes cumulées dépassent souvent la capacité du nœud. Quelle mesure aide le mieux à corriger le placement ?', 'Revoir requests, limits et capacité des nœuds à partir des mesures réelles et des profils de charge', ['Retirer toutes les requests pour autoriser le scheduler à mieux deviner', 'Augmenter uniquement le nombre de répliques des pods déjà en mémoire insuffisante', 'Désactiver les événements du scheduler'], 'Les requests influencent le placement, tandis que les limits bornent la consommation. Leur calibrage et la capacité des nœuds doivent refléter l’usage mesuré.'),
                    $this->q('Un contrôleur déploie automatiquement des images dont le tag est « latest ». Après une nouvelle publication, il est difficile d’identifier l’image exécutée précédemment. Quelle pratique améliore le plus la reproductibilité ?', 'Déployer des images référencées par digest immuable et conserver le lien avec la version source', ['Conserver le tag latest et documenter seulement l’heure du déploiement', 'Retirer les métadonnées de build des images', 'Construire une image différente sur chaque nœud au démarrage'], 'Un tag mutable peut désigner des contenus différents au fil du temps. Le digest identifie précisément l’artefact et facilite l’audit ou le rollback.'),
                    $this->q('Une application exposée à Internet utilise un secret Kubernetes stocké dans etcd. Quel contrôle complémentaire est essentiel ?', 'Protéger l’accès au secret par RBAC, chiffrement au repos et gestion de cycle de vie adaptée', ['Considérer le secret comme protégé parce que son contenu est encodé en Base64', 'Autoriser tous les utilisateurs du cluster à le lire pour simplifier les rotations', 'Publier le manifeste dans le dépôt public en masquant uniquement son nom'], 'L’encodage Base64 n’est pas du chiffrement. Les accès, le chiffrement au repos, la rotation et les journaux doivent être configurés selon la sensibilité du secret.'),
                    $this->q('Un cluster partage un même nœud entre workloads sensibles et workloads de test non fiables. Les limites CPU sont configurées, mais les exigences d’isolation restent fortes. Quelle décision d’architecture faut-il étudier ?', 'Séparer les pools de nœuds ou clusters selon le niveau de confiance et les exigences d’isolation', ['Augmenter seulement les limites CPU des workloads sensibles', 'Désactiver les probes de santé des workloads de test', 'Utiliser le même compte de service pour tous les namespaces'], 'Les limites de ressources réduisent la contention mais ne garantissent pas une isolation de sécurité suffisante entre charges de confiance différente.'),
                    $this->q('Une mise à jour de NetworkPolicy bloque par erreur le trafic vers le service de paiement. Quelle pratique de livraison réduit le mieux le risque de répétition ?', 'Valider les règles en préproduction, déployer progressivement et surveiller les flux et indicateurs métier', ['Appliquer toutes les politiques en production en une seule fois sans possibilité de retour', 'Désactiver les alertes réseau pendant la période de changement', 'Permettre tout le trafic sortant si une règle échoue'], 'Les politiques réseau peuvent interrompre des dépendances légitimes. Une validation réaliste, une progression contrôlée et une stratégie de rollback limitent l’impact.'),
                    $this->q('Un pod doit accéder à une ressource cloud sans clé statique. Quelle conception réduit le mieux le risque d’usurpation ou d’usage excessif ?', 'Associer une identité de workload vérifiable à un rôle cloud restreint et à durée limitée', ['Monter une clé administrateur commune depuis un volume partagé', 'Utiliser les identifiants personnels du développeur qui a créé le cluster', 'Placer une clé dans une variable d’environnement permanente de l’image'], 'L’identité de workload évite les secrets statiques dans le pod et permet d’appliquer des permissions précises, temporaires et attribuables.'),
                    $this->q('Un cluster multi-tenant présente des incidents où un namespace consomme toutes les adresses IP disponibles. Quel ensemble de garde-fous répond le mieux à la fois à la capacité et à l’isolation ?', 'Des quotas par namespace, une planification de capacité et une surveillance des ressources réseau', ['Un rôle IAM plus permissif pour chaque équipe', 'Un unique plafond de CPU appliqué aux nœuds sans suivi réseau', 'La suppression des probes de santé pour libérer des adresses'], 'Les quotas limitent la consommation par tenant; la planification et la surveillance révèlent les limites de capacité du cluster avant saturation.'),
                ],
            ],
            [
                'title' => 'Cloud Advanced — Serverless, files et traitement distribué',
                'description' => 'Concevez des traitements événementiels robustes face aux doublons, aux retards, aux pannes et aux pics de charge.',
                'difficulty' => 'Advanced',
                'duration' => 30,
                'passing_score' => 70,
                'total_marks' => 10,
                'is_active' => true,
                'questions' => [
                    $this->q('Un déclencheur de stockage livre parfois le même événement plusieurs fois. Le traitement crédite un compte client. Quelle protection est nécessaire ?', 'Dédupliquer avec un identifiant d’événement durable et rendre l’écriture de crédit idempotente', ['Augmenter la concurrence de la fonction afin que les doublons se terminent plus vite', 'Supposer que le fournisseur garantit une livraison exactement une fois dans tous les cas', 'Ignorer les identifiants d’événement et comparer uniquement le montant'], 'Les systèmes événementiels livrent souvent au moins une fois. La déduplication et l’idempotence évitent de reproduire un effet métier lors d’une livraison répétée.'),
                    $this->q('Une fonction consomme une file, mais le message réapparaît avant la fin du traitement et est pris par un second consommateur. Quel paramètre faut-il examiner en premier ?', 'La durée de visibilité ou de verrouillage doit dépasser le temps de traitement attendu, avec une extension contrôlée si nécessaire', ['La durée de rétention doit être réduite à zéro', 'La file doit accepter des messages sans identifiant', 'Le nombre de consommateurs doit être augmenté sans limite'], 'Si le message redevient visible avant la fin du traitement, plusieurs consommateurs peuvent le traiter en parallèle. La durée doit tenir compte de la latence et des reprises.'),
                    $this->q('Un consommateur échoue sur un type de message mal formé et bloque les messages valides placés derrière lui. Quelle stratégie permet de préserver le débit et d’isoler les erreurs persistantes ?', 'Appliquer un nombre limité de tentatives puis déplacer le message en échec vers une dead-letter queue avec alerte', ['Réessayer le message sans limite jusqu’à ce qu’il fonctionne', 'Supprimer automatiquement tous les messages de la file à la première erreur', 'Augmenter le timeout sans garder de trace de l’échec'], 'Une dead-letter queue isole les messages qui échouent de façon persistante. Les tentatives limitées et l’alerte permettent une correction sans bloquer tout le flux.'),
                    $this->q('Une fonction serverless traite les pointes en créant rapidement de nombreuses instances, mais la base de données sature sous le nombre de connexions. Quelle mesure traite le mieux le goulot d’étranglement ?', 'Contrôler la concurrence du traitement et utiliser un mécanisme de pool ou de proxy de connexions adapté', ['Augmenter uniquement la mémoire de chaque fonction', 'Accélérer le démarrage des fonctions sans limiter leur nombre', 'Envoyer chaque requête deux fois pour mieux utiliser la base'], 'La mise à l’échelle des fonctions peut dépasser la capacité de connexions de la base. Le contrôle de concurrence et la gestion des connexions doivent être conçus ensemble.'),
                    $this->q('Un événement peut être reçu avant que le service destinataire ne soit disponible. L’émetteur ne doit pas rester bloqué. Quelle interaction est la plus robuste ?', 'Publier l’événement dans un mécanisme durable et laisser le consommateur le traiter avec retries bornés', ['Attendre indéfiniment une réponse synchrone du destinataire', 'Supprimer l’événement si le premier appel échoue', 'Répéter immédiatement la publication sans identifiant de corrélation'], 'La mise en file durable découple la disponibilité temporelle des services. Les reprises doivent rester bornées et les traitements idempotents.'),
                    $this->q('Deux fonctions consomment des événements et terminent dans un ordre différent de leur arrivée. L’ordre n’est requis que par client. Quelle approche préserve l’échelle tout en respectant ce besoin ?', 'Partitionner par identifiant de client et traiter séquentiellement dans chaque partition', ['Utiliser une file globale à un seul consommateur pour tous les clients', 'Répartir au hasard et trier les résultats après les effets métier', 'Horodater les événements et supposer que les horloges sont parfaitement synchronisées'], 'Le partitionnement par client préserve l’ordre à l’intérieur d’une clé, tout en autorisant le parallélisme entre clients.'),
                    $this->q('Une chaîne serverless traverse six fonctions et une erreur entraîne plusieurs exécutions partielles. Quelle conception facilite la reprise et le diagnostic ?', 'Modéliser l’orchestration avec états explicites, délais, gestion d’erreurs et identifiants de corrélation', ['Laisser chaque fonction déclencher la suivante sans conserver d’état ni de contexte', 'Augmenter la durée maximale de toutes les fonctions sans définir de reprise', 'Garder les erreurs uniquement dans la mémoire de l’instance'], 'Une orchestration explicite rend les transitions et échecs visibles, permet des reprises ciblées et facilite le suivi d’une même exécution de bout en bout.'),
                    $this->q('Un traitement d’image peut prendre plus longtemps que la durée maximale d’une fonction. Quelle architecture convient le mieux ?', 'Découper le travail en tâches persistantes ou utiliser un service de traitement adapté aux exécutions longues', ['Augmenter les retries de la fonction sans réduire la durée du travail', 'Répondre au client avant le début du traitement puis supprimer la tâche', 'Conserver le fichier complet en mémoire dans une fonction d’API synchrone'], 'Les fonctions courtes conviennent aux tâches bornées. Un traitement long doit être découpé ou confié à un mécanisme conçu pour des jobs persistants.'),
                    $this->q('Après un déploiement, une file accumule des messages et le délai de traitement augmente. Quelle paire de mesures aide le mieux à distinguer un manque de capacité d’une panne de dépendance ?', 'Suivre l’âge du plus ancien message et le débit de consommation, puis corréler avec les erreurs et latences des dépendances', ['Suivre uniquement le nombre total d’instances et ignorer les erreurs', 'Surveiller le coût mensuel global sans métriques de file', 'Réduire la rétention des messages afin que la file paraisse plus petite'], 'L’âge des messages et le débit montrent l’évolution de la file; les erreurs et latences des dépendances indiquent si les consommateurs sont lents ou bloqués en aval.'),
                    $this->q('Une fonction est déclenchée à nouveau après un timeout du client, alors que le premier traitement a peut-être terminé. Quelle conception protège une opération non répétable ?', 'Enregistrer l’état de traitement avec une clé d’idempotence avant de produire l’effet externe', ['Augmenter le timeout client et considérer que les répétitions disparaîtront', 'Demander au client de ne jamais réessayer une requête', 'Renvoyer une erreur même si l’effet métier a été appliqué'], 'Un timeout ne prouve pas que le traitement a échoué. Un état durable associé à une clé d’idempotence permet de répondre de façon cohérente aux répétitions.'),
                ],
            ],
            [
                'title' => 'Cloud Advanced — Observabilité, fiabilité et réponse aux incidents',
                'description' => 'Utilisez SLI, SLO, traces et exercices opérationnels pour détecter et résoudre les dégradations cloud.',
                'difficulty' => 'Advanced',
                'duration' => 30,
                'passing_score' => 70,
                'total_marks' => 10,
                'is_active' => true,
                'questions' => [
                    $this->q('Une API affiche 99,9 % de disponibilité, mais les clients signalent des réponses très lentes lors des heures de pointe. Quel SLI complète le mieux la mesure existante ?', 'La proportion de requêtes réussissant sous un seuil de latence défini, segmentée par parcours ou classe de requêtes', ['Le nombre total de machines virtuelles provisionnées', 'La moyenne mensuelle de CPU de tous les comptes cloud', 'La durée de rétention des journaux sans mesure des requêtes'], 'La disponibilité seule ne décrit pas l’expérience. Un SLI de latence lié aux requêtes permet de mesurer les performances perçues et de distinguer les parcours.'),
                    $this->q('Une équipe consomme rapidement son error budget après une série de déploiements. Quelle décision de pilotage est la plus défendable ?', 'Réduire temporairement le rythme des changements risqués et prioriser les causes de fiabilité avant de reprendre', ['Continuer le même rythme car les déploiements sont déjà planifiés', 'Élargir le SLO pour que les incidents ne soient plus comptabilisés', 'Désactiver les alertes jusqu’au prochain trimestre'], 'Un budget d’erreur matérialise la marge de dégradation acceptable. Sa consommation rapide justifie de rééquilibrer les changements et le travail de fiabilité.'),
                    $this->q('Une alerte se déclenche chaque fois que le CPU dépasse 80 %, mais l’équipe découvre que les utilisateurs ne sont pas affectés. Quel ajustement améliore la valeur de l’alerte ?', 'Corréler la métrique à un symptôme de service et définir un seuil lié à l’impact ou à une action requise', ['Abaisser encore le seuil CPU pour recevoir plus d’alertes', 'Envoyer toutes les alertes directement aux utilisateurs finaux', 'Supprimer les métriques CPU et toute autre télémétrie'], 'Une alerte utile signale un impact ou un risque exploitable. Une métrique isolée peut créer des faux positifs si elle n’est pas reliée au comportement du service.'),
                    $this->q('Une requête lente traverse une passerelle, trois microservices et une base de données. Les journaux ont des formats différents et aucun identifiant commun. Quel ajout accélère le diagnostic ?', 'Propager un identifiant de trace et corréler les spans avec des journaux structurés', ['Augmenter la taille des journaux sans standardiser leur contexte', 'Réduire les services à un seul tableau de bord CPU', 'Supprimer les timestamps des événements pour éviter les écarts d’horloge'], 'Les traces distribuées montrent le parcours et la durée par dépendance. La corrélation avec des logs structurés relie les événements à une requête donnée.'),
                    $this->q('Les métriques d’une base sont normales, mais le traitement de commandes prend du retard. Quelle source de télémétrie révèle le mieux le point de blocage dans une chaîne asynchrone ?', 'L’âge du plus ancien message et le débit ou taux d’échec par étape du pipeline', ['Le nombre d’utilisateurs enregistrés sur le site', 'La taille des sauvegardes hebdomadaires uniquement', 'La moyenne CPU des postes de développement'], 'Une file peut s’accumuler même si chaque composant semble sain isolément. Les métriques de backlog, de débit et d’échec localisent l’étape qui n’absorbe plus la charge.'),
                    $this->q('Une équipe mesure la latence moyenne d’une API, mais quelques requêtes extrêmement lentes causent des échecs métier. Quel changement d’analyse est le plus utile ?', 'Examiner les percentiles élevés et segmenter les latences par opération ou dépendance', ['Arrondir la moyenne à l’entier le plus proche', 'Ne conserver que la latence minimale', 'Additionner toutes les latences sans tenir compte du nombre de requêtes'], 'La moyenne masque souvent la queue de distribution. Les percentiles élevés et la segmentation aident à identifier les retards rares mais importants.'),
                    $this->q('Une panne de région est simulée, mais l’exercice ne teste que la disponibilité du serveur web. Quelle lacune empêche de conclure sur la reprise du service ?', 'Les dépendances, données, identités, DNS et procédures opérationnelles n’ont pas été validés de bout en bout', ['Le serveur web a utilisé une image de conteneur trop récente', 'Le nombre de graphiques du tableau de bord est trop élevé', 'Le test a été exécuté en dehors des heures de bureau'], 'Un service fonctionnel dépend de plus que son frontal. Un exercice de reprise doit couvrir les dépendances et le parcours utilisateur, ainsi que les actions nécessaires à l’équipe.'),
                    $this->q('Un incident récurrent est résolu par redémarrage, mais aucune cause n’est connue et l’équipe ne suit pas le risque de retour. Quelle suite d’exploitation est la plus utile ?', 'Documenter l’incident, analyser les causes, créer des actions correctives et suivre leur efficacité', ['Fermer l’incident dès que le service répond de nouveau', 'Augmenter la fréquence des redémarrages automatiques sans suivi', 'Réduire la rétention des journaux après chaque incident'], 'La restauration du service n’élimine pas nécessairement la cause. Une analyse suivie d’actions vérifiables réduit la répétition et améliore la réponse future.'),
                    $this->q('Un changement de routage entraîne une hausse du taux d’erreur après déploiement progressif à 5 % du trafic. Quel mécanisme devrait arrêter l’élargissement du déploiement ?', 'Une analyse automatique ou une règle d’arrêt basée sur des indicateurs de santé et des seuils définis', ['Un calendrier fixe qui augmente le trafic indépendamment des résultats', 'Un avis d’approbation envoyé après la fin du déploiement', 'Une alerte basée uniquement sur le volume de stockage'], 'Un canary doit être évalué sur des signaux pertinents. Des seuils d’arrêt empêchent de propager une régression détectée sur le petit périmètre.'),
                    $this->q('Une équipe reçoit de nombreuses alertes de sécurité et de performance sans responsable identifié. Quelle amélioration réduit le plus le risque d’alertes ignorées ?', 'Attribuer les alertes à des services et équipes, préciser l’action attendue et tester périodiquement les escalades', ['Augmenter le nombre de destinataires sans préciser de propriétaire', 'Désactiver les alertes la nuit même pour les services critiques', 'Regrouper tous les événements dans un canal sans priorité'], 'Une alerte doit être actionnable, priorisée et attribuée. Les exercices d’escalade confirment que les bonnes personnes peuvent intervenir dans les délais attendus.'),
                ],
            ],
            [
                'title' => 'Cloud Advanced — Migration, modernisation et bascule',
                'description' => 'Choisissez des stratégies de migration fondées sur les dépendances, les objectifs, les risques de bascule et le retour arrière.',
                'difficulty' => 'Advanced',
                'duration' => 30,
                'passing_score' => 70,
                'total_marks' => 10,
                'is_active' => true,
                'questions' => [
                    $this->q('Un portefeuille applicatif contient des services interdépendants, mais l’inventaire des flux est incomplet. Quel travail devrait précéder le choix des vagues de migration ?', 'Cartographier les dépendances techniques et métier, puis valider les propriétaires et contraintes de chaque application', ['Migrer d’abord les applications les plus visibles sans analyser leurs dépendances', 'Choisir les vagues uniquement selon la taille des machines virtuelles', 'Déplacer les bases de données avant de connaître les applications qui les utilisent'], 'Les dépendances déterminent l’ordre et la portée d’une migration. Une cartographie validée limite les interruptions causées par un composant oublié.'),
                    $this->q('Une application stable doit quitter un datacenter avant une échéance proche. Elle n’exploite pas encore les fonctions natives du cloud, mais une réécriture complète est trop risquée. Quelle stratégie peut être raisonnable ?', 'Migrer d’abord avec des changements limités, puis moderniser les composants selon une analyse de valeur et de risque', ['Réécrire immédiatement tous les modules avant tout test de migration', 'Supprimer les contrôles d’intégrité pour respecter l’échéance', 'Remplacer l’application par un service aléatoire de même capacité'], 'Une migration par étapes peut répondre à une contrainte de calendrier tout en évitant une réécriture risquée. Les optimisations peuvent suivre lorsque leur valeur est démontrée.'),
                    $this->q('Un système possède des dépendances à une version de base de données non disponible dans le service managé cible. Quelle décision de migration est la plus solide ?', 'Évaluer les options de compatibilité, de mise à niveau et de maintien temporaire avant de choisir un chemin avec critères de validation', ['Ignorer la dépendance et supposer que le service cible acceptera le format', 'Copier les fichiers de données sans tester leur cohérence', 'Mettre en production la version cible avant de mesurer les écarts'], 'Les contraintes de compatibilité peuvent modifier le coût et la séquence de migration. Chaque option doit être évaluée selon le risque, la durée de support et les critères de validation.'),
                    $this->q('Une bascule DNS est prévue, mais les clients et résolveurs peuvent conserver l’ancienne adresse pendant un certain temps. Quel plan réduit le risque de routage vers un système arrêté ?', 'Réduire le TTL à l’avance, maintenir une période de coexistence contrôlée et valider les flux avant l’arrêt de l’ancien système', ['Arrêter l’ancien système au moment exact de la modification DNS', 'Augmenter le TTL plusieurs jours avant la bascule', 'Modifier uniquement le fichier hosts du poste de l’administrateur'], 'La propagation DNS n’est pas instantanée. Une coexistence et un retour arrière contrôlés absorbent les clients qui continuent d’utiliser l’ancienne résolution.'),
                    $this->q('La réplication des données vers le cloud est terminée, mais des écritures continuent sur l’ancien système pendant la bascule. Quel contrôle est essentiel avant de considérer la migration réussie ?', 'Geler ou synchroniser les écritures selon un plan défini, puis vérifier les écarts et l’intégrité avant réouverture', ['Comparer seulement le volume total des bases', 'Supprimer les journaux de transaction de l’ancien système', 'Ouvrir les deux bases en écriture sans stratégie de conflit'], 'Les volumes égaux ne garantissent pas des données identiques. Le plan doit contrôler la dernière synchronisation, les écarts et la cohérence des écritures.'),
                    $this->q('Une migration pilote fonctionne pour une équipe, mais cette équipe utilise peu de fonctions de la plateforme. Quelle conclusion est la plus prudente ?', 'Le pilote ne valide pas encore les contraintes et dépendances des autres profils d’application', ['Toutes les applications du portefeuille peuvent désormais être migrées de la même manière', 'Le pilote prouve que les objectifs de performance sont atteints pour toute charge', 'Il faut supprimer l’inventaire puisque la première migration a réussi'], 'Un pilote apporte des preuves limitées à son périmètre. La stratégie doit couvrir d’autres profils représentatifs et leurs contraintes avant généralisation.'),
                    $this->q('Un service migré consomme deux fois plus de ressources que prévu et son temps de réponse s’est dégradé. Quel contrôle devrait faire partie de la décision de clôture de migration ?', 'Comparer les performances et coûts réels aux objectifs, examiner les causes et valider les critères d’acceptation métier', ['Clore le projet parce que les machines sont désormais dans le cloud', 'Augmenter toutes les capacités sans mesurer les goulets d’étranglement', 'Comparer uniquement le nombre de ressources avant et après'], 'Le déplacement technique ne prouve pas la réussite. Les critères doivent inclure la qualité de service, les coûts et les résultats attendus.'),
                    $this->q('Une équipe envisage de découper un monolithe avant migration parce qu’elle souhaite « être cloud-native ». L’application est stable, et aucun besoin de changement rapide par composant n’a été démontré. Quelle évaluation est la plus pertinente ?', 'Comparer le bénéfice mesurable du découpage à son coût de transformation, de réseau, de tests et d’exploitation', ['Adopter les microservices par principe, indépendamment des besoins', 'Conserver le monolithe sans vérifier les limites opérationnelles', 'Augmenter le nombre de services jusqu’à atteindre un standard arbitraire'], 'La modernisation doit répondre à un besoin métier ou opérationnel. Les microservices ajoutent des coûts et des modes de panne qui doivent être justifiés par des bénéfices.'),
                    $this->q('Le plan de migration d’une base ne prévoit pas de retour arrière après l’ouverture des écritures dans le nouvel environnement. Pourquoi ce point doit-il être traité avant la bascule ?', 'Le retour peut devenir incohérent une fois que les systèmes divergent; il faut définir la capture ou la réconciliation des nouvelles écritures', ['Un retour arrière est toujours possible par simple redémarrage', 'La réplication garantit automatiquement la synchronisation dans les deux sens', 'Les écritures métier n’ont aucune valeur pendant une migration'], 'Après l’ouverture des écritures, revenir à l’ancien système nécessite une stratégie de synchronisation ou de réconciliation. Ce scénario doit être conçu et testé à l’avance.'),
                    $this->q('Une application a été migrée mais son équipe n’a ni droits cloud adaptés, ni procédure d’incident, ni indicateurs de service. Quelle étape manque à la migration ?', 'La préparation opérationnelle avec responsabilités, accès, observabilité, runbooks et critères de support', ['L’ajout d’un deuxième logo au portail cloud', 'L’activation de tous les droits administrateur à l’équipe', 'La suppression des procédures de l’ancien environnement avant le transfert de connaissance'], 'Une charge migrée doit pouvoir être exploitée. Les responsabilités, accès, indicateurs et procédures font partie des critères de mise en service.'),
                ],
            ],
            [
                'title' => 'Cloud Advanced — FinOps, gouvernance et optimisation mesurée',
                'description' => 'Diagnostiquez les coûts unitaires, les dérives de consommation, les garde-fous et les arbitrages de valeur.',
                'difficulty' => 'Advanced',
                'duration' => 30,
                'passing_score' => 70,
                'total_marks' => 10,
                'is_active' => true,
                'questions' => [
                    $this->q('Une plateforme traite deux fois plus de commandes pour une hausse de coût cloud de 10 %. Quel indicateur aide le mieux à évaluer l’évolution de l’efficacité économique ?', 'Le coût cloud par commande, comparé sur des périodes et périmètres équivalents', ['La facture totale seule, sans tenir compte du volume traité', 'Le nombre de comptes cloud sans lien avec la production', 'La taille de la région hébergeant le service'], 'Le coût unitaire relie la dépense à l’activité métier. Il aide à distinguer une croissance de consommation liée au volume d’une dégradation d’efficacité.'),
                    $this->q('Une équipe reçoit une alerte de budget après que la dépense a déjà doublé. Quelle mesure permettrait de réduire le délai de détection sans bloquer toute expérimentation ?', 'Combiner budgets prévisionnels, anomalies de consommation et alertes par propriétaire ou produit', ['Désactiver les alertes jusqu’à la clôture mensuelle', 'Afficher uniquement le coût annuel consolidé de l’organisation', 'Interdire toutes les nouvelles ressources sans processus d’exception'], 'Les budgets seuls peuvent réagir tardivement. Les détections d’anomalies et l’attribution aux propriétaires permettent d’enquêter plus tôt tout en gardant une voie de gouvernance.'),
                    $this->q('Des machines réservées couvrent un profil d’utilisation devenu rare après une refonte. Quelle démarche est la plus appropriée avant de renouveler l’engagement ?', 'Analyser l’utilisation réelle, les changements prévus et les options d’échange ou de réduction de l’engagement', ['Renouveler automatiquement la même quantité pour conserver la remise historique', 'Augmenter l’engagement afin de réduire le prix affiché par heure', 'Supprimer les mesures d’utilisation qui montrent la sous-consommation'], 'Les engagements réduisent parfois le tarif mais créent un risque de capacité inutilisée. La décision doit s’appuyer sur les profils observés et les prévisions crédibles.'),
                    $this->q('Une équipe réduit les tailles de toutes ses bases après avoir observé une faible utilisation CPU moyenne. Des pics de fin de mois provoquent ensuite des timeouts. Quelle amélioration du processus aurait évité cette régression ?', 'Évaluer les distributions et périodes de pointe, les SLO et la marge de capacité avant de modifier les ressources', ['Se baser exclusivement sur la moyenne de CPU annuelle', 'Désactiver les timeouts afin que les clients attendent plus longtemps', 'Réduire aussi la capacité de secours pour confirmer les économies'], 'Une moyenne peut masquer des pointes. Le rightsizing doit respecter les profils de charge et les objectifs de performance, avec validation des périodes critiques.'),
                    $this->q('Les coûts de transfert de données augmentent après le déplacement d’un service analytique dans une région différente de celle des sources. Quel diagnostic est prioritaire ?', 'Cartographier les flux et mesurer les volumes transférés entre services, régions et zones', ['Compter seulement les machines virtuelles du service analytique', 'Réduire la rétention des journaux sans examiner le trafic', 'Modifier les tags des ressources sans regarder les transferts'], 'Les transferts interrégionaux ou entre zones peuvent contribuer fortement à la facture. La topologie et les volumes doivent être rapprochés des coûts observés.'),
                    $this->q('Une politique préventive bloque les ressources non conformes, mais plusieurs équipes contournent le processus et créent des copies hors plateforme. Quel changement de gouvernance est le plus utile ?', 'Associer des garde-fous proportionnés à des parcours approuvés faciles à utiliser et à une procédure d’exception traçable', ['Rendre les contrôles encore plus stricts sans proposer de solution conforme', 'Supprimer les contrôles préventifs et examiner la facture en fin d’année', 'Accorder des droits administrateur à toutes les équipes'], 'Une gouvernance durable combine contrôle et adoption. Des services de plateforme approuvés et des exceptions suivies réduisent l’incitation au contournement.'),
                    $this->q('Un tableau FinOps attribue tous les coûts partagés à une seule équipe, même si plusieurs produits consomment le service. Quelle amélioration rend la répartition plus utile ?', 'Définir une règle d’allocation documentée fondée sur un inducteur représentatif de la consommation', ['Répartir le montant au hasard chaque mois', 'Imputer tout le coût à l’équipe qui a créé le compte cloud', 'Masquer les coûts partagés des rapports produits'], 'Les coûts partagés doivent être répartis selon une règle explicite et stable, par exemple l’usage mesuré. Une attribution arbitraire fausse les décisions des équipes.'),
                    $this->q('Une optimisation économise 15 % mais augmente le taux d’erreur d’un service critique au-delà de son SLO. Quelle conclusion FinOps est la plus fondée ?', 'L’économie ne constitue pas une amélioration acceptable tant que le compromis de fiabilité et de valeur n’est pas résolu', ['Toute réduction de facture est une réussite FinOps', 'Le SLO doit être abandonné dès qu’il limite les économies', 'Les erreurs ne doivent pas être prises en compte dans une analyse de coût'], 'FinOps cherche la valeur, pas la réduction brute des dépenses. Une économie qui viole les objectifs de fiabilité doit être réévaluée avec les responsables métier et techniques.'),
                    $this->q('Une équipe crée des environnements de test qui restent actifs pendant les nuits et les fins de semaine. Certains tests nécessitent toutefois une exécution continue. Quelle politique évite les économies aveugles ?', 'Appliquer des horaires aux environnements admissibles, prévoir des exceptions documentées et surveiller les arrêts non souhaités', ['Arrêter toutes les ressources sans distinction chaque soir', 'Laisser toutes les ressources actives parce que certaines sont nécessaires', 'Supprimer automatiquement les environnements après une seule journée'], 'L’arrêt planifié réduit le gaspillage, mais doit tenir compte des besoins de test. Les exceptions et les métriques permettent d’éviter de casser des travaux légitimes.'),
                    $this->q('Une organisation impose une région cloud unique, mais un produit exige une reprise dans une région secondaire. Comment traiter ce conflit de gouvernance ?', 'Documenter l’exigence, évaluer les risques et coûts, puis obtenir une exception approuvée avec contrôles adaptés', ['Déployer secrètement dans une autre région pour respecter le RTO', 'Ignorer le besoin de reprise puisque la politique est générale', 'Modifier la politique pour tous les produits sans analyse'], 'Les règles générales peuvent nécessiter des exceptions motivées. Une décision transparente doit équilibrer localisation, continuité, conformité, coûts et contrôles.'),
                ],
            ],
            [
                'title' => 'Cloud Advanced — Reprise après sinistre et scénarios d’architecture',
                'description' => 'Résolvez des scénarios avancés de continuité, de sécurité et de choix d’architecture sous contraintes explicites.',
                'difficulty' => 'Advanced',
                'duration' => 35,
                'passing_score' => 70,
                'total_marks' => 10,
                'is_active' => true,
                'questions' => [
                    $this->q('Une application de paiement exige un RTO de dix minutes et un RPO proche de zéro. La région secondaire est rarement utilisée et les tests de bascule sont manuels. Quelle analyse doit guider l’investissement ?', 'Vérifier si l’architecture, la réplication, les dépendances et les procédures peuvent démontrer ces objectifs lors de tests réguliers', ['Conserver les sauvegardes mensuelles, car le RPO ne concerne que la disponibilité', 'Augmenter le nombre de machines dans la région principale sans tester la reprise', 'Déclarer les objectifs atteints sur la base de la configuration nominale'], 'Le RTO et le RPO sont des objectifs mesurables. La réplication, les dépendances et les équipes doivent démontrer leur capacité à les respecter en exercice.'),
                    $this->q('Une sauvegarde est immuable, mais le compte qui peut restaurer les données peut aussi modifier les politiques de rétention. Quelle faiblesse subsiste ?', 'Une identité compromise peut potentiellement réduire les protections ou déclencher une restauration non fiable', ['L’immuabilité garantit que les politiques ne peuvent jamais être modifiées', 'Le stockage objet ne permet pas de restaurer des données', 'La seule faiblesse est la latence du DNS'], 'L’immutabilité protège les objets selon une politique, mais les rôles capables de modifier les règles ou la restauration doivent être séparés et fortement contrôlés.'),
                    $this->q('Une reprise multi-région satisfait le RTO lors d’un exercice, mais les utilisateurs voient des données plus anciennes que prévu. Quel objectif n’a pas été validé ?', 'Le RPO et la cohérence des données après la bascule', ['La durée de vie du certificat TLS', 'La capacité des postes de travail des opérateurs', 'Le coût de stockage des journaux uniquement'], 'Le temps de reprise et la perte de données sont deux objectifs distincts. Un exercice doit vérifier la fraîcheur et l’intégrité des données restaurées.'),
                    $this->q('Un fournisseur tiers de DNS, une identité centrale et une région cloud sont des dépendances communes à toutes les zones d’une application. Pourquoi une architecture multi-zone seule ne suffit-elle pas ?', 'Ces dépendances partagées peuvent provoquer une panne commune malgré la redondance des composants applicatifs', ['Les zones de disponibilité ne peuvent jamais héberger des applications web', 'La redondance augmente automatiquement le RPO à zéro', 'Une panne DNS n’affecte que les bases de données'], 'La redondance des instances ne couvre pas les dépendances communes. L’analyse de résilience doit inclure DNS, identité, réseau, données et services externes.'),
                    $this->q('Un exercice de reprise démontre que l’équipe peut restaurer les serveurs, mais personne ne sait qui autorise le basculement ni qui informe les utilisateurs. Quel élément de continuité manque ?', 'Les responsabilités, critères de déclenchement, communications et procédures de décision', ['Une seconde copie du logo dans le portail cloud', 'Une métrique de CPU plus détaillée uniquement', 'Un nouveau nom de région pour les serveurs de secours'], 'La reprise dépend des décisions et communications autant que de la technologie. Les rôles et critères d’activation doivent être définis et exercés.'),
                    $this->q('Une région secondaire réplique en continu depuis la production. Une attaque chiffre les données logiques, puis le chiffrement est répliqué. Quelle protection aurait réduit le risque de perdre les points de restauration antérieurs ?', 'Des sauvegardes versionnées et isolées, avec rétention immuable et identités de sauvegarde séparées', ['Une réplication plus rapide vers la même région', 'La suppression des journaux de transaction après chaque écriture', 'Une seule sauvegarde en ligne avec le même compte d’administration que la production'], 'La réplication peut propager une corruption logique. Des points de restauration isolés et protégés permettent de revenir à un état antérieur sain.'),
                    $this->q('Une architecture active-active sert des utilisateurs dans deux régions, mais une panne réseau crée des écritures concurrentes. Quelle décision doit être explicite dans la conception ?', 'La stratégie de propriété des données et de résolution des conflits, avec son impact sur les opérations métier', ['Le nom de la région affichée dans le tableau de bord', 'La couleur utilisée pour les métriques de réplication', 'L’ordre alphabétique des noms de services'], 'Active-active améliore la disponibilité mais rend les écritures concurrentes possibles. La résolution doit préserver les invariants métier et être comprise par les équipes.'),
                    $this->q('Une application est considérée critique, mais son propriétaire n’a jamais défini les conséquences métier d’une interruption. Quel travail doit précéder le choix d’une architecture de reprise coûteuse ?', 'Établir l’impact métier, les tolérances RTO/RPO et les dépendances prioritaires avec les parties concernées', ['Choisir d’abord une architecture active-active puis demander aux métiers de s’y adapter', 'Prendre le RTO le plus court possible sans analyser le coût', 'Réutiliser l’objectif d’une autre application sans comparaison'], 'Les objectifs de reprise doivent refléter les conséquences d’une interruption. Ils servent à choisir un niveau de résilience proportionné plutôt qu’à surinvestir ou sous-protéger.'),
                    $this->q('Un test de reprise restaure les données dans les délais, mais les secrets de chiffrement ne sont pas disponibles dans la région cible. Quelle dépendance avait été omise ?', 'La disponibilité et l’autorisation d’utiliser les clés nécessaires à la restauration', ['La mise en forme du tableau de bord FinOps', 'Le système de nommage des images de conteneurs uniquement', 'La politique de rotation des mots de passe des utilisateurs finaux'], 'Les données chiffrées ne sont pas utilisables sans accès aux clés. Les clés, leurs politiques et les identités de reprise font partie du plan de continuité.'),
                    $this->q('Une organisation veut réduire le risque de panne fournisseur, mais son équipe ne peut pas exploiter deux plateformes cloud avec des contrôles équivalents. Quelle décision est la plus responsable ?', 'Comparer le risque fournisseur aux risques opérationnels et aux coûts d’une stratégie multicloud réellement exploitable', ['Adopter immédiatement deux fournisseurs sans former les équipes', 'Ignorer la dépendance fournisseur parce qu’un contrat la supprime entièrement', 'Répliquer chaque service managé manuellement sans tester les écarts'], 'Le multicloud peut réduire certaines dépendances mais ajoute complexité et besoins de compétences. Le choix doit comparer les risques réels, la capacité d’exploitation et les coûts.'),
                ],
            ],
        ];

        foreach ($quizzes as $quizData) {
            $quiz = Quiz::updateOrCreate(
                [
                    'subject_id' => $subject->id,
                    'title' => $quizData['title'],
                ],
                [
                    'owner_id' => null,
                    'description' => $quizData['description'],
                    'duration' => $quizData['duration'],
                    'passing_score' => $quizData['passing_score'],
                    'total_marks' => $quizData['total_marks'],
                    'is_active' => $quizData['is_active'],
                    'difficulty' => $quizData['difficulty'],
                ]
            );

            foreach ($quizData['questions'] as $index => $questionData) {
                $question = Question::updateOrCreate(
                    [
                        'quiz_id' => $quiz->id,
                        'order' => $index + 1,
                    ],
                    [
                        'question' => $questionData['question'],
                        'type' => 'multiple_choice',
                        'marks' => 1,
                        'explanation' => $questionData['explanation'],
                    ]
                );

                $question->choices()->delete();

                $choices = $questionData['choices'];
                shuffle($choices);

                foreach ($choices as $choiceIndex => $choice) {
                    Choice::create([
                        'question_id' => $question->id,
                        'choice_text' => $choice['choice_text'],
                        'is_correct' => $choice['is_correct'],
                        'order' => $choiceIndex + 1,
                    ]);
                }
            }
        }
    }

    private function q(string $question, string $answer, array $distractors, string $explanation): array
    {
        $choices = [['choice_text' => $answer, 'is_correct' => true]];

        foreach ($distractors as $distractor) {
            $choices[] = ['choice_text' => $distractor, 'is_correct' => false];
        }

        return [
            'question' => $question,
            'explanation' => $explanation,
            'choices' => $choices,
        ];
    }
}
